css:
.hero__caption {
  position: fixed;
  z-index: 4;
  left: clamp(24px, 3.85vw, 78px);
  bottom: 28px;
  display: inline-flex;
  align-items: center;
  gap: 24px;
  max-width: min(170px, calc(50vw - 112px));
  margin: 0;
  color: rgb(42 42 42 / 0.58);
  font-size: 16px;
  font-weight: 400;
  line-height: 22px;
  letter-spacing: 0;
  transform: translate3d(0, var(--scroll-y, 0px), 0);
  will-change: transform, opacity;
}
